-- An agreed repayment plan is a reviewed source record, not a journal or a forecast.
CREATE VIEW installment_contract_state AS
 SELECT l.id AS loan_id,
 json_object('loan',json_array(l.id,l.member_id,l.principal_minor,l.currency,l.disbursement_date,l.terms),
 'void',EXISTS(SELECT 1 FROM loan_source_voids v WHERE v.source_kind='loan' AND v.source_id=l.id),
 'config',(SELECT json_array(c.request_key,c.rate_basis_points,c.period_days,c.principal_minor,c.currency,c.disbursement_date,c.reviewed_terms) FROM loan_billing_configs c WHERE c.loan_id=l.id),
 'opening',(SELECT json_array(o.journal_id,o.opening_date,o.principal_minor) FROM loan_openings o WHERE o.loan_id=l.id),
 'openingState',(SELECT json_array(s.request_key,s.interest_due_minor,s.recognized_interest_minor,s.minimum_assessed,s.cutoff_rate_basis_points,s.cutoff_period_days) FROM loan_billing_opening_states s WHERE s.loan_id=l.id),
 'rates',coalesce((SELECT json_group_array(json_array(id,effective_date,rate_basis_points,period_days)) FROM (SELECT c.id,c.effective_date,c.rate_basis_points,c.period_days FROM loan_billing_rate_changes c WHERE c.loan_id=l.id AND NOT EXISTS(SELECT 1 FROM loan_billing_rate_change_voids v WHERE v.change_id=c.id) ORDER BY c.effective_date,c.id)),'[]'),
 'legacy',(SELECT json_array(r.id,r.status,EXISTS(SELECT 1 FROM json_each(r.mappings) x WHERE json_type(x.value,'$.rateId')='text' AND NOT EXISTS(SELECT 1 FROM loan_billing_rate_changes c WHERE c.id=json_extract(x.value,'$.rateId') AND NOT EXISTS(SELECT 1 FROM loan_billing_rate_change_voids v WHERE v.change_id=c.id)))) FROM loan_billing_legacy_reviews r JOIN loan_billing_configs c ON c.loan_id=r.loan_id AND c.request_key=r.config_request_key WHERE r.loan_id=l.id)) AS signature
 FROM loans l;
CREATE TABLE loan_installment_plans (
 id TEXT PRIMARY KEY, loan_id TEXT NOT NULL REFERENCES loans(id),config_key TEXT NOT NULL,expected_revision INTEGER NOT NULL,
 previous_id TEXT REFERENCES loan_installment_plans(id), request_key TEXT NOT NULL UNIQUE, created_by TEXT NOT NULL,
 source TEXT NOT NULL, reason TEXT NOT NULL,coverage_start TEXT NOT NULL,history_complete INTEGER NOT NULL CHECK(history_complete IN (0,1)),
 opening_payment_history TEXT NOT NULL CHECK(opening_payment_history IN ('known','none','unknown')), opening_last_applied_date TEXT,
 rows_json TEXT NOT NULL CHECK(json_valid(rows_json) AND json_type(rows_json)='array'),contract_signature TEXT NOT NULL,
 created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TRIGGER installment_plan_validate BEFORE INSERT ON loan_installment_plans BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM app_user_roles WHERE user_id=NEW.created_by AND role='admin') OR NOT EXISTS(SELECT 1 FROM loan_billing_configs c JOIN loans l ON l.id=c.loan_id JOIN loan_billing_revisions r ON r.loan_id=c.loan_id JOIN installment_contract_state s ON s.loan_id=c.loan_id WHERE c.loan_id=NEW.loan_id AND c.request_key=NEW.config_key AND r.revision=NEW.expected_revision AND s.signature=NEW.contract_signature AND NOT EXISTS(SELECT 1 FROM loan_source_voids v WHERE v.source_kind='loan' AND v.source_id=l.id) AND NEW.coverage_start>=l.disbursement_date AND (NEW.history_complete=0 OR NEW.coverage_start=coalesce((SELECT o.opening_date FROM loan_openings o WHERE o.loan_id=l.id),l.disbursement_date)) AND NOT EXISTS(SELECT 1 FROM loan_openings o WHERE o.loan_id=l.id AND (NEW.coverage_start<o.opening_date OR NOT EXISTS(SELECT 1 FROM loan_billing_opening_states b WHERE b.loan_id=o.loan_id AND b.opening_journal_id=o.journal_id AND b.cutoff_rate_basis_points IS NOT NULL AND b.cutoff_period_days IS NOT NULL))) AND NOT EXISTS(SELECT 1 FROM loan_billing_legacy_reviews x WHERE x.loan_id=l.id AND x.config_request_key=c.request_key AND (x.status<>'final' OR EXISTS(SELECT 1 FROM json_each(x.mappings) z WHERE json_type(z.value,'$.rateId')='text' AND NOT EXISTS(SELECT 1 FROM loan_billing_rate_changes k WHERE k.id=json_extract(z.value,'$.rateId') AND NOT EXISTS(SELECT 1 FROM loan_billing_rate_change_voids w WHERE w.change_id=k.id)))))) THEN RAISE(ABORT,'schedule review stale or unauthorized') END;
 SELECT CASE WHEN (SELECT id FROM loan_installment_plans WHERE loan_id=NEW.loan_id ORDER BY rowid DESC LIMIT 1) IS NOT NEW.previous_id THEN RAISE(ABORT,'schedule version changed') END;
 SELECT CASE WHEN length(trim(NEW.source)) NOT BETWEEN 1 AND 450 OR length(trim(NEW.reason)) NOT BETWEEN 1 AND 450 OR length(NEW.coverage_start)<>10 OR date(NEW.coverage_start,'+0 days') IS NOT NEW.coverage_start OR json_array_length(NEW.rows_json) NOT BETWEEN 1 AND 120 THEN RAISE(ABORT,'invalid schedule details') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM json_each(NEW.rows_json) x WHERE json_type(x.value,'$.dueDate') IS NOT 'text' OR length(json_extract(x.value,'$.dueDate'))<>10 OR date(json_extract(x.value,'$.dueDate'),'+0 days') IS NOT json_extract(x.value,'$.dueDate') OR json_extract(x.value,'$.dueDate')<(SELECT disbursement_date FROM loans WHERE id=NEW.loan_id) OR (NEW.history_complete=1 AND NOT EXISTS(SELECT 1 FROM loan_openings WHERE loan_id=NEW.loan_id) AND json_extract(x.value,'$.dueDate')<NEW.coverage_start) OR json_type(x.value,'$.principalMinor') IS NOT 'text' OR json_type(x.value,'$.interestMinor') IS NOT 'text' OR length(json_extract(x.value,'$.principalMinor')) NOT BETWEEN 1 AND 16 OR length(json_extract(x.value,'$.interestMinor')) NOT BETWEEN 1 AND 16 OR json_extract(x.value,'$.principalMinor') GLOB '*[^0-9]*' OR json_extract(x.value,'$.interestMinor') GLOB '*[^0-9]*' OR (length(json_extract(x.value,'$.principalMinor'))>1 AND substr(json_extract(x.value,'$.principalMinor'),1,1)='0') OR (length(json_extract(x.value,'$.interestMinor'))>1 AND substr(json_extract(x.value,'$.interestMinor'),1,1)='0') OR (json_extract(x.value,'$.principalMinor')='0' AND json_extract(x.value,'$.interestMinor')='0')) OR EXISTS(SELECT 1 FROM json_each(NEW.rows_json) a JOIN json_each(NEW.rows_json) b ON CAST(b.key AS INTEGER)=CAST(a.key AS INTEGER)+1 WHERE json_extract(a.value,'$.dueDate')>=json_extract(b.value,'$.dueDate')) THEN RAISE(ABORT,'invalid installment rows') END;
 SELECT CASE WHEN (NEW.opening_payment_history='known' AND (NEW.opening_last_applied_date IS NULL OR date(NEW.opening_last_applied_date,'+0 days') IS NOT NEW.opening_last_applied_date OR NEW.opening_last_applied_date<(SELECT disbursement_date FROM loans WHERE id=NEW.loan_id) OR NEW.opening_last_applied_date>(SELECT opening_date FROM loan_openings WHERE loan_id=NEW.loan_id))) OR (NEW.opening_payment_history<>'known' AND NEW.opening_last_applied_date IS NOT NULL) OR (NOT EXISTS(SELECT 1 FROM loan_openings WHERE loan_id=NEW.loan_id) AND (NEW.opening_payment_history<>'none' OR NEW.opening_last_applied_date IS NOT NULL)) THEN RAISE(ABORT,'invalid reviewed opening payment history') END;
 SELECT CASE WHEN NEW.history_complete=1 AND EXISTS(SELECT 1 FROM loan_billing_opening_states WHERE loan_id=NEW.loan_id AND interest_due_minor>(SELECT sum(CAST(json_extract(x.value,'$.interestMinor') AS INTEGER)) FROM json_each(NEW.rows_json) x)) THEN RAISE(ABORT,'complete schedule must cover opening unpaid interest') END;
 SELECT CASE WHEN NEW.history_complete=1 AND (SELECT sum(CAST(json_extract(x.value,'$.principalMinor') AS INTEGER)) FROM json_each(NEW.rows_json) x) IS NOT coalesce((SELECT principal_minor FROM loan_openings WHERE loan_id=NEW.loan_id),(SELECT principal_minor FROM loans WHERE id=NEW.loan_id)) THEN RAISE(ABORT,'complete schedule principal must match reviewed loan or opening') END;
END;
CREATE TRIGGER installment_plan_immutable BEFORE UPDATE ON loan_installment_plans BEGIN SELECT RAISE(ABORT,'installment plan immutable'); END;
CREATE TRIGGER installment_plan_no_delete BEFORE DELETE ON loan_installment_plans BEGIN SELECT RAISE(ABORT,'installment plan immutable'); END;
